export function lookupPlayerId(nameOrSlug?: string | null): number | null {
  if (!nameOrSlug) return null;
  const raw = String(nameOrSlug).trim();
  if (!raw) return null;

  // Direct numeric check
  if (/^\d+$/.test(raw)) {
    return Number(raw);
  }

  const clean = raw.toLowerCase().replace(/[^a-z0-9]/g, ' ').trim().split(/\s+/).filter(Boolean);
  if (clean.length === 0) return null;

  const joined = clean.join(' ');
  if (PLAYER_ID_MAP[joined]) return PLAYER_ID_MAP[joined];

  const hyphen = clean.join('-');
  if (PLAYER_ID_MAP[hyphen]) return PLAYER_ID_MAP[hyphen];

  if (clean.length > 1) {
    const p1 = clean[0];
    const pLast = clean[clean.length - 1];

    const initialHyphen = p1[0] + '-' + pLast;
    if (PLAYER_ID_MAP[initialHyphen]) return PLAYER_ID_MAP[initialHyphen];

    const initialSpace = p1[0] + ' ' + pLast;
    if (PLAYER_ID_MAP[initialSpace]) return PLAYER_ID_MAP[initialSpace];

    const lastFirst = pLast + ' ' + p1[0];
    if (PLAYER_ID_MAP[lastFirst]) return PLAYER_ID_MAP[lastFirst];

    const lastFirstFull = pLast + ' ' + p1;
    if (PLAYER_ID_MAP[lastFirstFull]) return PLAYER_ID_MAP[lastFirstFull];
  }

  return null;
}
